    /** The translated notes for a settings table tag (lower case, as L10n reads it), or null. */
    public static String translated(String tag) {
        if (tag == null) return null;
        switch (tag) {
            case "az":
                return NOTES_AZ;
            case "de":
                return NOTES_DE;
            case "es":
                return NOTES_ES;
            case "in":
            case "id":
                return NOTES_IN;
            case "it":
                return NOTES_IT;
            case "pt-rbr":
                return NOTES_PT_RBR;
            case "ru":
                return NOTES_RU;
            case "tr":
                return NOTES_TR;
            default: return null;
        }
    }

